/**
 * @method
 * @name bitstamp#fetchMarkets
 * @description retrieves data on all markets for bitstamp
 * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetTradingPairsInfo
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Bitstamp) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.FetchMarketsFromCacheAsync(params))
	PanicOnError(response)
	//
	//    [
	//
	//   spot:
	//
	//        {
	//            "name": "BTC/USD",
	//            "market_symbol": "btcusd",
	//            "base_currency": "BTC",
	//            "base_decimals": 8,
	//            "counter_currency": "USD",
	//            "counter_decimals": 0,
	//            "minimum_order_value": "10",
	//            "trading": "Enabled",
	//            "instant_order_counter_decimals": 2,
	//            "instant_and_market_orders": "Enabled",
	//            "description": "Bitcoin / U.S. dollar",
	//            "market_type": "SPOT"
	//        },
	//        ...
	//
	//    perp:
	//
	//         {
	//             "name": "BTC/USD-PERP",
	//             "market_symbol": "btcusd-perp",
	//             "base_currency": "BTC",
	//             "base_decimals": 5,
	//             "counter_currency": "USD",
	//             "counter_decimals": 0,
	//             "minimum_order_value": "10",
	//             "maximum_order_value": "500000.00000000",
	//             "minimum_order_amount": "0.00001000",
	//             "maximum_order_amount": "10.00000000",
	//             "trading": "Enabled",
	//             "instant_order_counter_decimals": 2,
	//             "instant_and_market_orders": "Enabled",
	//             "description": "Bitcoin / U.S. dollar Perpetual",
	//             "market_type": "PERPETUAL",
	//             "underlying_asset": "Kaiko BTC Benchmark Reference Rate",
	//             "payoff_type": "Linear",
	//             "contract_size": "1.00000000",
	//             "isin": "EZHKD4DNKHY3"
	//         }
	//
	var result any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(response)); i++ {
		var market any = GetValue(response, i)
		baseIdquoteIdVariable := []any{this.SafeString(market, "base_currency"), this.SafeString(market, "counter_currency")}
		baseId := GetValue(baseIdquoteIdVariable, 0)
		quoteId := GetValue(baseIdquoteIdVariable, 1)
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		var settleId any = nil
		var marketTypeRaw *string = this.SafeString(market, "market_type")
		var symbol any = Add(Add(base, "/"), quote)
		var typeVar any = nil
		var subType any = nil
		if marketTypeRaw != nil && *marketTypeRaw == "SPOT" {
			typeVar = "spot"
		} else if marketTypeRaw != nil && *marketTypeRaw == "PERPETUAL" {
			typeVar = "swap"
			settleId = quoteId
			symbol = Add(Add(Add(Add(base, "/"), quote), ":"), settleId)
			var payoffType *string = this.SafeString(market, "payoff_type")
			if payoffType != nil && *payoffType == "Linear" {
				subType = "linear"
			} else if payoffType != nil && *payoffType == "Inverse" {
				subType = "inverse"
			}
		}
		var isSpot bool = (IsEqual(typeVar, "spot"))
		var settle any = Ternary((!IsEqual(settleId, nil) && (!IsEqual(settleId, ""))), this.SafeCurrencyCode(settleId), nil)
		AppendToArray(&result, map[string]any{
			"id":             this.SafeString(market, "market_symbol"),
			"symbol":         symbol,
			"base":           base,
			"quote":          quote,
			"settle":         settle,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       settleId,
			"type":           typeVar,
			"subType":        subType,
			"spot":           isSpot,
			"margin":         false,
			"future":         false,
			"swap":           !isSpot,
			"option":         false,
			"active":         (IsEqual(this.SafeString(market, "trading"), "Enabled")),
			"contract":       !isSpot,
			"linear":         Ternary(isSpot, nil, true),
			"inverse":        Ternary(isSpot, nil, false),
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber(this.ParsePrecision(this.SafeString(market, "base_decimals"))),
				"price":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "counter_decimals"))),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(market, "minimum_order_amount"),
					"max": this.SafeNumber(market, "maximum_order_amount"),
				},
				"price": map[string]any{
					"min": nil,
					"max": nil,
				},
				"cost": map[string]any{
					"min": this.SafeNumber(market, "minimum_order_value"),
					"max": this.SafeNumber(market, "maximum_order_value"),
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- result
	return nil
}
func (this *Bitstamp) ConstructCurrencyObject(id any, code any, name any, precision any, minCost any, originalPayload any) any {
	var currencyType string = "crypto"
	var description any = this.Describe()
	if EvalTruthy(this.IsFiat(code)) {
		currencyType = "fiat"
	}
	var tickSize any = this.ParseNumber(this.ParsePrecision(this.NumberToString(precision)))
	return map[string]any{
		"id":        id,
		"code":      code,
		"info":      originalPayload,
		"type":      currencyType,
		"name":      name,
		"active":    true,
		"deposit":   nil,
		"withdraw":  nil,
		"fee":       this.SafeNumber(GetValue(GetValue(GetValue(description, "fees"), "funding"), "withdraw"), code),
		"precision": tickSize,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": tickSize,
				"max": nil,
			},
			"price": map[string]any{
				"min": tickSize,
				"max": nil,
			},
			"cost": map[string]any{
				"min": minCost,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": map[string]any{},
	}
}
func (this *Bitstamp) FetchMarketsFromCacheAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsFromCacheBody(ch, optionalArgs...)
	return ch
}
func (this *Bitstamp) fetchMarketsFromCacheBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// this method is now redundant
	// currencies are now fetched before markets
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	var options any = this.SafeValue(this.Options, "fetchMarkets", map[string]any{})
	var timestamp *int64 = this.SafeInteger(options, "timestamp")
	var expires *int64 = this.SafeInteger(options, "expires", 1000)
	var now int64 = this.Milliseconds()
	if (timestamp == nil) || (IsGreaterThan((Subtract(now, timestamp)), expires)) {

		response := (<-this.PublicGetMarkets(params))
		PanicOnError(response)
		//
		//    [
		//        {
		//            "name": "BTC/USD",
		//            "market_symbol": "btcusd",
		//            "base_currency": "BTC",
		//            "base_decimals": 8,
		//            "counter_currency": "USD",
		//            "counter_decimals": 0,
		//            "minimum_order_value": "10",
		//            "trading": "Enabled",
		//            "instant_order_counter_decimals": 2,
		//            "instant_and_market_orders": "Enabled",
		//            "description": "Bitcoin / U.S. dollar",
		//            "market_type": "SPOT"
		//        },
		//
		AddElementToObject(this.Options, "fetchMarkets", this.Extend(options, map[string]any{
			"response":  response,
			"timestamp": now,
		}))
	}

	ch <- this.SafeValue(GetValue(this.Options, "fetchMarkets"), "response")
	return nil
}

