func (this *Bitstamp) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDepositsWithdrawals
	//
	//     {
	//         "fee": "0.00000000",
	//         "btc_usd": "0.00",
	//         "id": 1234567894,
	//         "usd": 0,
	//         "btc": 0,
	//         "datetime": "2018-09-08 09:00:31",
	//         "type": "1",
	//         "xrp": "-20.00000000",
	//         "eur": 0,
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "status": 2,
	//         "datetime": "2018-10-17 10:58:13",
	//         "currency": "BTC",
	//         "amount": "0.29669259",
	//         "address": "aaaaa",
	//         "type": 1,
	//         "id": 111111,
	//         "transaction_id": "xxxx",
	//     }
	//
	//     {
	//         "id": 3386432,
	//         "type": 14,
	//         "amount": "863.21332500",
	//         "status": 2,
	//         "address": "rE1sdh25BJQ3qFwngiTBwaq3zPGGYcrjp1?dt=1455",
	//         "currency": "XRP",
	//         "datetime": "2018-01-05 15:27:55",
	//         "transaction_id": "001743B03B0C79BA166A064AC0142917B050347B4CB23BA2AB4B91B3C5608F4C"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.Parse8601(this.SafeString(transaction, "datetime"))
	var currencyId any = this.GetCurrencyIdFromTransaction(transaction)
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var feeCost *string = this.SafeString(transaction, "fee")
	var feeCurrency any = nil
	var amount any = nil
	if InOp(transaction, "amount") {
		amount = DerefScalar(this.SafeString(transaction, "amount"))
	} else if !IsEqual(currency, nil) {
		amount = DerefScalar(this.SafeString(transaction, GetValue(currency, "id"), amount))
		feeCurrency = GetValue(currency, "code")
	} else if (code != nil) && (!IsEqual(currencyId, nil)) {
		amount = DerefScalar(this.SafeString(transaction, currencyId, amount))
		feeCurrency = code
	}
	if !IsEqual(amount, nil) {
		// withdrawals have a negative amount
		amount = Precise.StringAbs(amount)
	}
	var status any = "ok"
	if InOp(transaction, "status") {
		status = this.ParseTransactionStatus(this.SafeString(transaction, "status"))
	}
	var typeVar any = nil
	if InOp(transaction, "type") {
		// from fetchDepositsWithdrawals
		var rawType *string = this.SafeString(transaction, "type")
		if rawType != nil && *rawType == "0" {
			typeVar = "deposit"
		} else if rawType != nil && *rawType == "1" {
			typeVar = "withdrawal"
		}
	} else {
		// from fetchWithdrawals
		typeVar = "withdrawal"
	}
	var tag any = nil
	var address any = DerefScalar(this.SafeString(transaction, "address"))
	if !IsEqual(address, nil) {
		// dt (destination tag) is embedded into the address field
		var addressParts []string = Split(address, "?dt=")
		var numParts int = GetArrayLength(addressParts)
		if IsGreaterThan(numParts, 1) {
			address = GetValue(addressParts, 0)
			tag = GetValue(addressParts, 1)
		}
	}
	var fee map[string]any = map[string]any{
		"currency": nil,
		"cost":     nil,
		"rate":     nil,
	}
	if feeCost != nil {
		fee = map[string]any{
			"currency": feeCurrency,
			"cost":     feeCost,
			"rate":     nil,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "transaction_id"),
		"type":        typeVar,
		"currency":    code,
		"network":     nil,
		"amount":      this.ParseNumber(amount),
		"status":      status,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     address,
		"addressFrom": nil,
		"addressTo":   address,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
	}
}
func (this *Bitstamp) ParseTransactionStatus(status any) *string {
	//
	//   withdrawals:
	//   0 (open), 1 (in process), 2 (finished), 3 (canceled) or 4 (failed).
	//
	var statuses map[string]any = map[string]any{
		"0": "pending",
		"1": "pending",
		"2": "ok",
		"3": "canceled",
		"4": "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitstamp) ParseOrder(order any, optionalArgs ...any) any {
	//
	//   from fetch order:
	//     { status: "Finished",
	//       "id": 731693945,
	//       "client_order_id": '',
	//       "transactions":
	//       [ { fee: "0.000019",
	//           "price": "0.00015803",
	//           "datetime": "2018-01-07 10:45:34.132551",
	//           "btc": "0.0079015000000000",
	//           "tid": 42777395,
	//           "type": 2,
	//           "xrp": "50.00000000" } ] }
	//
	//   partially filled order:
	//     { "id": 468646390,
	//       "client_order_id": "",
	//       "status": "Canceled",
	//       "transactions": [{
	//           "eth": "0.23000000",
	//           "fee": "0.09",
	//           "tid": 25810126,
	//           "usd": "69.8947000000000000",
	//           "type": 2,
	//           "price": "303.89000000",
	//           "datetime": "2017-11-11 07:22:20.710567"
	//       }]}
	//
	//   from create order response:
	//       {
	//           "price": "0.00008012",
	//           "client_order_id": '',
	//           "currency_pair": "XRP/BTC",
	//           "datetime": "2019-01-31 21:23:36",
	//           "amount": "15.00000000",
	//           "type": "0",
	//           "id": "2814205012"
	//       }
	//
	// cancelOrder
	//
	//    {
	//        "id": 1453282316578816,
	//        "amount": "0.02035278",
	//        "price": "2100.45",
	//        "type": 0,
	//        "market": "BTC/USD"
	//    }
	//
	// editOrder
	//
	//    {
	//        "order_id": 1453282316578816,
	//        "order_type": "0",
	//        "market": "BTC/USD",
	//        "amount": "0.02035278",
	//        "price": "2100.45",
	//        "datetime": "2025-10-17T14:23:01.725000Z",
	//        "orig_order_id": 1453282316578816,
	//        "orig_client_order_id": "my-original-order-123",
	//        "status": "Open"
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString2(order, "id", "order_id")
	var clientOrderId *string = this.SafeString2(order, "client_order_id", "orig_client_order_id")
	var side any = DerefScalar(this.SafeString2(order, "type", "order_type"))
	if !IsEqual(side, nil) {
		side = Ternary((IsEqual(side, "1")), "sell", "buy")
	}
	// there is no timestamp from fetchOrder
	var timestamp *int64 = this.Parse8601(this.SafeString(order, "datetime"))
	var marketId *string = this.SafeStringLower(order, "currency_pair")
	var symbol *string = this.SafeSymbol(marketId, market, "/")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var amount *string = this.SafeString(order, "amount")
	var transactions any = this.SafeValue(order, "transactions", []any{})
	var price *string = this.SafeString(order, "price")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"datetime":           this.Iso8601(timestamp),
		"timestamp":          timestamp,
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               nil,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          nil,
		"trades":             transactions,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}
func (this *Bitstamp) ParseLedgerEntryType(typeVar any) *string {
	var types map[string]any = map[string]any{
		"0":  "transaction",
		"1":  "transaction",
		"2":  "trade",
		"14": "transfer",
	}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Bitstamp) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	//     [
	//         {
	//             "fee": "0.00000000",
	//             "btc_usd": "0.00",
	//             "id": 1234567894,
	//             "usd": 0,
	//             "btc": 0,
	//             "datetime": "2018-09-08 09:00:31",
	//             "type": "1",
	//             "xrp": "-20.00000000",
	//             "eur": 0,
	//         },
	//         {
	//             "fee": "0.00000000",
	//             "btc_usd": "0.00",
	//             "id": 1134567891,
	//             "usd": 0,
	//             "btc": 0,
	//             "datetime": "2018-09-07 18:47:52",
	//             "type": "0",
	//             "xrp": "20.00000000",
	//             "eur": 0,
	//         },
	//     ]
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var typeVar *string = this.ParseLedgerEntryType(this.SafeString(item, "type"))
	if typeVar != nil && *typeVar == "trade" {
		var parsedTrade any = this.ParseTrade(item)
		var market any = nil
		var keys []string = ObjectKeys(item)
		for i := 0; IsLessThan(i, GetArrayLength(keys)); i++ {
			if IsGreaterThanOrEqual(GetIndexOf(GetValue(keys, i), "_"), 0) {
				var marketId string = Replace(GetValue(keys, i), "_", "")
				market = this.SafeMarket(marketId, market)
			}
		}
		// if the market is still not defined
		// try to deduce it from used keys
		if IsEqual(market, nil) {
			market = this.GetMarketFromTrade(item)
		}
		var direction any = Ternary((IsEqual(GetValue(parsedTrade, "side"), "buy")), "in", "out")
		return this.SafeLedgerEntry(map[string]any{
			"info":             item,
			"id":               GetValue(parsedTrade, "id"),
			"timestamp":        GetValue(parsedTrade, "timestamp"),
			"datetime":         GetValue(parsedTrade, "datetime"),
			"direction":        direction,
			"account":          nil,
			"referenceId":      GetValue(parsedTrade, "order"),
			"referenceAccount": nil,
			"type":             typeVar,
			"currency":         this.SafeString(market, "base"),
			"amount":           GetValue(parsedTrade, "amount"),
			"before":           nil,
			"after":            nil,
			"status":           "ok",
			"fee":              GetValue(parsedTrade, "fee"),
		}, currency)
	} else {
		var parsedTransaction any = this.ParseTransaction(item, currency)
		var direction any = nil
		if InOp(item, "amount") {
			var amount *string = this.SafeString(item, "amount")
			direction = Ternary(Precise.StringGt(amount, "0"), "in", "out")
		} else if (InOp(parsedTransaction, "currency")) && !IsEqual(GetValue(parsedTransaction, "currency"), nil) {
			var currencyCode *string = this.SafeString(parsedTransaction, "currency")
			currency = this.Currency(currencyCode)
			var amount *string = this.SafeString(item, GetValue(currency, "id"))
			direction = Ternary(Precise.StringGt(amount, "0"), "in", "out")
		}
		return this.SafeLedgerEntry(map[string]any{
			"info":             item,
			"id":               GetValue(parsedTransaction, "id"),
			"timestamp":        GetValue(parsedTransaction, "timestamp"),
			"datetime":         GetValue(parsedTransaction, "datetime"),
			"direction":        direction,
			"account":          nil,
			"referenceId":      GetValue(parsedTransaction, "txid"),
			"referenceAccount": nil,
			"type":             typeVar,
			"currency":         GetValue(parsedTransaction, "currency"),
			"amount":           GetValue(parsedTransaction, "amount"),
			"before":           nil,
			"after":            nil,
			"status":           GetValue(parsedTransaction, "status"),
			"fee":              GetValue(parsedTransaction, "fee"),
		}, currency)
	}
}

